    def is_free(pos):
        px, py = pos
        if not (0 <= px < len(grid) and 0 <= py < len(grid[0])):
            return False
        return grid[px][py] == 0  # assuming 0 means free, other values blocked

    # Generate candidate moves
    candidate_moves = [(-1, 0), (1, 0), (0, -1), (0, 1), (0,0)]

