        elif dy != 0:
            move[1] = 1 if dy > 0 else -1
        # Check if move is free
        new_pos = (x + move[0], y + move[1])
        if is_free(new_pos):
            return move
        # Else, try other moves towards resource
        for dm in candidate_moves:
            nx, ny = x + dm[0], y + dm[1]
            if is_free((nx, ny)):
                return list(dm)

    # For pursuit evasion: move away from nearest opponent
    if opponents:
