        if target_positions:
            # pick nearest
            def dist_t(pos):
                return abs(pos[0]-x) + abs(pos[1]-y)
            nearest_tpos = min(target_positions, key=dist_t)
            dx = nearest_tpos[0] - x
            dy = nearest_tpos[1] - y
            move = [0, 0]
            if dx != 0:
                move[0] = 1 if dx > 0 else -1
            elif dy != 0:
                move[1] = 1 if dy > 0 else -1
